CRIT_SPLIT = {"A": 7, "B": 9, "C": 4, "D": 5}
H = lambda a, b: [a, b]

def arith(a, d, n): return a + (n - 1) * d
def arith_sum(a, d, n): return n / 2 * (2 * a + (n - 1) * d)
def geom(a, r, n): return a * r ** (n - 1)
def geom_sum(a, r, n): return a * (r ** n - 1) / (r - 1)

